IF NOT EXISTS (SELECT 1 FROM dbo.blood_request_matches WHERE request_id = @requestPending AND donor_id = @donorNilaId) INSERT INTO dbo.blood_request_matches (request_id, donor_id, match_score, compatibility_label, status, notified_at, selected_by_user_id, notes, created_at, updated_at) VALUES (@requestPending, @donorNilaId, 98.50, N'Exact', N'Notified', DATEADD(HOUR, -1, @now), @itBloodId, N'Priority O- donor notified.', DATEADD(HOUR, -1, @now), DATEADD(HOUR, -1, @now));
IF NOT EXISTS (SELECT 1 FROM dbo.blood_request_matches WHERE request_id = @requestApproved AND donor_id = @donorArifId) INSERT INTO dbo.blood_request_matches (request_id, donor_id, match_score, compatibility_label, status, notified_at, responded_at, selected_by_user_id, notes, created_at, updated_at) VALUES (@requestApproved, @donorArifId, 95.20, N'Exact', N'Accepted', DATEADD(HOUR, -14, @now), DATEADD(HOUR, -13, @now), @itBloodId, N'Donor accepted and waiting fulfillment.', DATEADD(HOUR, -14, @now), DATEADD(HOUR, -13, @now));
DECLARE @matchPending BIGINT = (SELECT TOP 1 id FROM dbo.blood_request_matches WHERE request_id = @requestPending AND donor_id = @donorNilaId);
