DECLARE @hcArif BIGINT = (SELECT TOP 1 id FROM dbo.donor_health_checks WHERE donor_id = @donorArifId ORDER BY id DESC);
IF NOT EXISTS (SELECT 1 FROM dbo.blood_donations WHERE donor_id = @donorArifId AND linked_request_id = @requestApproved) INSERT INTO dbo.blood_donations (donor_id, blood_bank_id, donation_datetime, blood_group, component_type, units_donated, recorded_by_user_id, linked_request_id, donor_health_check_id, notes, created_at, updated_at) VALUES (@donorArifId, @bankCentralId, DATEADD(HOUR, -2, @now), N'A+', N'WholeBlood', 1, @itBloodId, @requestApproved, @hcArif, N'Donation logged for approved request.', DATEADD(HOUR, -2, @now), DATEADD(HOUR, -2, @now));

